  ["4738b1c8938d0492"] = { "Shhh! Mi fai scappare i pesci.", "." },
  ["473ec40fbc34e630"] = { "Cervello sfondato... mortaio... sfra... cellato... perde... muo... io...", "." },
  ["47433483bd0d8bf3"] = { "È mio dovere e mio onore morire per l'Abyssal Council!", "." },
  ["4748987b3ac38977"] = { "Vuoi il mio aiuto? Ce l'hai. Di cosa hai bisogno?", "." },
