  ["475938aab59d6b34"] = { "Nelle giornate limpide da qui si vede persino il ⟦Blackrock Mountain=Massiccio Roccianera⟧. È al tempo stesso bellissimo e terrificante.", "." },
  ["4759db9c81bac275"] = { "Troverai l'istruttore dei maghi, ⟦Cain Firesong=Cain Cantafuoco⟧, al piano di sopra, sul pianerottolo della ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧, all'estremità sud-orientale di Brill. Credo che abbia preso alloggio troppo tardi per avere una stanza.", "." },
  ["4760a888d757f635"] = { "Mi serve un passaggio.", "." },
  ["4761cd0695929b55"] = { "%s comincia a sprigionare fumo e prende fuoco! Hai la sensazione di dover SCAPPARE!", "." },
  ["4769c047a010f78e"] = { "Io sono ⟦Balgaras the Foul=Balgaras l'Infetto⟧. E tu, {name}, stai per diventare nient'altro che cenere e polvere.", "." },
  ["476a9fd89049cf1e"] = { "Parla con il satiro prigioniero", "." },
  ["476af8c4b5742ab5"] = { "Posso andare a raccogliere altre pietre per la mia collana, papà?", "." },
  ["4771c2f623d487df"] = { "La tua astuzia è davvero cresciuta, {name}.", "." },
  ["4772a8d0dfd86173"] = { "Il collare è davvero intriso di potere demoniaco, {name}. Questo non promette nulla di buono per il nostro popolo.", "." },
  ["47733f5831ce46ea"] = { "Il dottore è arrivato!", "." },
  ["477a91cae8aca68e"] = { "Chi va là?", "." },
  ["4781d4e0e5d2bc8c"] = { "Per cosa ti pago? I kodo sono quasi morti!", "." },
  ["478fe4851f87445d"] = { "Altro?", "." },
  ["479148e52539864d"] = { "L'abilità di Byancie nel ⟦First Aid=Primo Soccorso⟧ si è rivelata utile in molte occasioni. Se vuoi imparare da lei, la trovi appena a nord della locanda di Dolanaar.", "." },
  ["4795a472f4751160"] = { "È tutta colpa loro, stupidi orchi. Hanno dovuto bruciare la mia fattoria fino alle fondamenta.", "." },
  ["4796ed04c40c5a5a"] = { "La ⟦Darkmoon Faire=Fiera di Lunacupa⟧ è arrivata in città! Non perderti lo spettacolo più emozionante che tu abbia mai visto!", "." },
  ["4796ed22c40c5a78"] = { "La ⟦Darkmoon Faire=Fiera di Lunacupa⟧ è arrivata in città! Non perderti lo spettacolo più emozionante che tu abbia mai visto?", "." },
  ["4797c005591022a3"] = { "Auguri di stagione, e pace a te!", "." },
  ["479c8ff4281497dd"] = { "Agente, puoi dirmi cosa sta succedendo qui negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧?", "." },
  ["47a69c2b8850d66b"] = { "Che le spire dell'odio si dispieghino!", "." },
  ["47a81e8f6ae667d0"] = { "Salute, {class}. Insegno conciatura qui a ⟦Thunder Bluff=Picco del Tuono⟧. In cosa posso esserti utile?", "." },
  ["47ac8e0d94aa744b"] = { "Nessuno passerà!", "." },
  ["47ae06859c1a7ccf"] = { "Noi... stiamo... indagando.", "." },
  ["47b97c33e2b93147"] = { "Il tuo tradimento non fa che affrettare la tua rovina. Questo mondo cadrà nelle tenebre!", "." },
  ["47c8940b2d978cf5"] = { "Senza dubbio la Dama Oscura mi manda l'ennesima testa vuota buona a nulla da addestrare sotto il suo campione.\n\n<Nathanos sospira.>\n\nVi ho rimandati tutti da lei a pezzi, e non vedo perché questa volta dovrebbe andare diversamente.\n\nTuttavia, non spetta a me chiedermi il perché, ma fare ciò che la Dama Oscura comanda.", "." },
  ["47cb4088caa479e8"] = { "Salute, {race}, sono ⟦Tharnariun Treetender=Tharnariun Lieveramo⟧.", "." },
  ["47dc40d7e8bd8e34"] = { "Di recente i Ferroscuro si fanno vedere in superficie sempre più spesso. Hanno costruito fortezze nelle ⟦Badlands=Maleterre⟧. Hanno mandato enormi spedizioni nelle profondità di Uldaman in cerca di antiche conoscenze. Hanno perfino invaso la nostra patria, colpendo la nostra diga vicino al lago.", "." },
  ["47e304d3022539bf"] = { "Buongiorno, <cittadino/cittadina>. Sei qui per aiutarci contro il Flagello?", "." },
  ["47e46cdd11bc7ce2"] = { "Me la pagherai! È colpa tua se devo farlo!", "." },
  ["47e588eddd6f2ef8"] = { "Tutti i preparativi sono completi, {class}. Aspettiamo che l'ultimo carico di materiale parta per ⟦Silithus=Silitus⟧, cosa che dovrebbe avvenire in meno di $2113w giorni. Poi, una volta che laggiù avranno finito di organizzarsi, qualcuno dovrà farsi avanti e suonare il gong sull'Altare dello Scarabeo con lo Scettro delle Sabbie Mutevoli. Sarà allora che comincerà la guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Che la Madre Terra vegli su tutti noi, in quel momento.", "." },
  ["47ed4f3d41057e5d"] = { "Perché ci vuole così tanto?", "." },
  ["47ee0c19a28147d1"] = { "Brock. Torren. Entro a farmi una birra e a scaldarmi accanto al fuoco.", "." },
  ["47ee2acbc030eed2"] = { "Sei <venuto/venuta> a imparare, eh, amico?", "." },
  ["47f0d35f7f40660e"] = { "Thunderaan non sapeva nulla delle mosse del Signore del Fuoco. Prima che il mio signore potesse reagire, Sulfuras, il leggendario martello di Ragnaros, gli inferse un colpo spietato. Thunderaan cadde, sconfitto senza scampo.\n\nIl Signore del Fuoco si nutrì dell'essenza del mio signore, ma non riuscì a divorarlo del tutto.", "." },
  ["47feda41b38d4166"] = { "A-Me casa! A-Me, buono! Buono A-Me. Casa. Casa. Casa.", "." },
